diff --git a/crates/nu_plugin_polars/src/dataframe/values/nu_dataframe/conversion.rs b/crates/nu_plugin_polars/src/dataframe/values/nu_dataframe/conversion.rs
index 0cc1878823d28c62aaf4bbded03c386cc1389de8..bc28caf092703ae144da81403a8f2d923f72193f 100644
--- a/crates/nu_plugin_polars/src/dataframe/values/nu_dataframe/conversion.rs
+++ b/crates/nu_plugin_polars/src/dataframe/values/nu_dataframe/conversion.rs
@@ -1218,0 +1219,25 @@ fn series_to_values(
+        DataType::Duration(time_unit) => {
+            let casted = series.duration().map_err(|e| ShellError::GenericError {
+                error: "Error casting column to duration".into(),
+                msg: "".into(),
+                span: None,
+                help: Some(e.to_string()),
+                inner: vec![],
+            })?;
+
+            let it = casted.into_iter();
+            let values = if let (Some(size), Some(from_row)) = (maybe_size, maybe_from_row) {
+                Either::Left(it.skip(from_row).take(size))
+            } else {
+                Either::Right(it)
+            }
+            .map(|v| match v {
+                Some(a) => {
+                    let nanos = nanos_from_timeunit(a, *time_unit)?;
+                    Ok(Value::duration(nanos, span))
+                }
+                None => Ok(Value::nothing(span)),
+            })
+            .collect::<Result<Vec<Value>, ShellError>>()?;
+            Ok(values)
+        }

